INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Benutzerdokumentation immer erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "Unterstützt Nutzer bei Bedienung"}, {"text": "Nein", "correct": false, "because": "Selten entbehrlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element priorisiere ich in einem Handbuch?', 3, '[{"text": "Anleitungsschritte", "correct": true, "because": "Klarheit für Nutzer"}, {"text": "Technische Details", "correct": false, "because": "Sekundär für Benutzer"}, {"text": "Kostenübersicht", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Schulungsmaterial effektiv?', 5, '[{"text": "Verständlichkeit", "correct": true, "because": "Erleichtert Lernen"}, {"text": "Praxisbeispiele", "correct": true, "because": "Zeigt Anwendung"}, {"text": "Minimaler Umfang", "correct": false, "because": "Details nötig"}, {"text": "Technische Tiefe", "correct": false, "because": "Für Experten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Handbücher erklären Bedienung. b) Schulungsmaterial ist nur für Profis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, für alle Nutzer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Handbuch für eine Web-App?', 4, '[{"text": "Bedienungsanleitung", "correct": false, "because": "Kern der Dokumentation"}, {"text": "Screenshots", "correct": false, "because": "Visuelle Unterstützung"}, {"text": "Programmierdetails", "correct": true, "because": "Nicht benutzerrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schulungsmaterial ohne Beispiele nützlich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Beispiele fördern Verständnis"}, {"text": "Ja", "correct": false, "because": "Weniger anschaulich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Benutzerhandbuch?', 3, '[{"text": "Einfache Bedienung", "correct": true, "because": "Nutzer unterstützen"}, {"text": "Technische Analyse", "correct": false, "because": "Nicht primär"}, {"text": "Kostensenkung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Schulungsmaterial?', 5, '[{"text": "Wissensvermittlung", "correct": true, "because": "Nutzer schulen"}, {"text": "Selbstständigkeit", "correct": true, "because": "Weniger Support nötig"}, {"text": "Geringer Aufwand", "correct": false, "because": "Erstellung zeitintensiv"}, {"text": "Technische Tiefe", "correct": false, "because": "Nicht benutzerfokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Handbücher sind für Anfänger. b) Schulungsmaterial ersetzt Support. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt Support"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Handbuch?', 4, '[{"text": "Schritt-für-Schritt-Anleitung", "correct": false, "because": "Kern der Nutzung"}, {"text": "Fehlerbehebung", "correct": false, "because": "Hilft bei Problemen"}, {"text": "Entwickler-Notizen", "correct": true, "because": "Nicht benutzerrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Handbuch ohne Bilder verständlich?', 2, '[{"text": "Ja", "correct": true, "because": "Text kann ausreichen"}, {"text": "Nein", "correct": false, "because": "Bilder oft hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für Schulungsmaterial entscheidend?', 4, '[{"text": "Praxisnähe", "correct": true, "because": "Fördert Anwendung"}, {"text": "Verständlichkeit", "correct": true, "because": "Erleichtert Lernen"}, {"text": "Technische Details", "correct": false, "because": "Für Experten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Benutzerdokumentation nur für Software ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Hardware"}, {"text": "Ja", "correct": false, "because": "Breiter einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in einem Handbuch für eine Datenbank?', 3, '[{"text": "Bedienungsanweisung", "correct": true, "because": "Nutzer unterstützen"}, {"text": "Code-Beispiele", "correct": false, "because": "Sekundär"}, {"text": "Kostenübersicht", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schulungsmaterial braucht Beispiele. b) Handbücher sind für Experten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, für alle Nutzer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein unvollständiges Handbuch?', 5, '[{"text": "Verwirrung", "correct": true, "because": "Nutzer fehlen Infos"}, {"text": "Mehr Support", "correct": true, "because": "Fragen bleiben offen"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Nicht vorteilhaft"}, {"text": "Hohe Lesbarkeit", "correct": false, "because": "Eher unklar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Schulungsmaterial für ein Netzwerk unwichtig?', 3, '[{"text": "Grundfunktionen", "correct": false, "because": "Kern des Lernens"}, {"text": "Beispiele", "correct": false, "because": "Fördern Verständnis"}, {"text": "Entwicklerdetails", "correct": true, "because": "Nicht benutzerrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Benutzerdokumentation aktuell gehalten werden?', 3, '[{"text": "Ja", "correct": true, "because": "Änderungen abbilden"}, {"text": "Nein", "correct": false, "because": "Veraltet nutzlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Handbücher nur Text enthalten sollten?', 2, '[{"text": "Nein", "correct": true, "because": "Bilder und Diagramme helfen"}, {"text": "Ja", "correct": false, "because": "Visuelle Hilfen nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Material wähle ich für neue Nutzer?', 4, '[{"text": "Handbuch mit Schulungsmaterial", "correct": true, "because": "Umfassend und praxisnah"}, {"text": "Nur Handbuch", "correct": false, "because": "Fehlt Praxis"}, {"text": "Kurze Notizen", "correct": false, "because": "Zu oberflächlich"}]');
